//! Golden vectors for sessions: `test-vectors/session-v1.json`.
//!
//! Generated by [`document`] (`cargo run -p fermata-verdict -- session-vectors`) and asserted
//! byte for byte by this crate's tests, the session contract's tests (which settle the recorded
//! batches on-chain with the recorded signatures), the SDK and `test-vectors/check_vectors.py`.
//! The encodings are specified in `docs/session-escrow.md`, section 10.

use ed25519_dalek::SigningKey;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

use crate::{
    keys,
    session::{self, Entry, Statement},
    to_hex,
    vectors::{self, SignerVector, SIGNER_SEED},
    Domain, TESTNET_PASSPHRASE,
};

/// The agent's ticket key: 31 zero bytes and a 2.
pub const TICKET_KEY_SEED: [u8; 32] = {
    let mut seed = [0u8; 32];
    seed[31] = 2;
    seed
};
/// The session contract's id: 30 zero bytes then 0x5e55.
pub const CONTRACT_ID: [u8; 32] = {
    let mut id = [0u8; 32];
    id[30] = 0x5e;
    id[31] = 0x55;
    id
};
/// The predicate hash of the vector service (as in `verdict-v1.json`).
pub const PREDICATE_HASH: [u8; 32] = [0x44; 32];
/// Every call proved (k = 1).
pub const SESSION_ID: [u8; 32] = [0x5a; 32];
/// One call in four proved (k = 4), batches of 8.
pub const SAMPLED_SESSION_ID: [u8; 32] = [0x5b; 32];
pub const SAMPLE_K: u32 = 4;
pub const BATCH_SIZE: u32 = 8;
/// The secret at the end of the verifier's seed chain for the sampled session (two batches).
pub const SEED_SECRET: [u8; 32] = [0x5c; 32];

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Document {
    pub description: String,
    pub ticket_tag: String,
    pub batch_tag: String,
    pub call_tag: String,
    pub network_passphrase: String,
    pub network_id: String,
    pub contract: String,
    pub contract_id: String,
    pub service_id: String,
    pub predicate_hash: String,
    pub verifier: SignerVector,
    pub ticket_key: SignerVector,
    pub sessions: Vec<SessionVector>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct SessionVector {
    pub name: String,
    pub session_id: String,
    pub sample_k: u32,
    pub batch_size: u32,
    /// `seeds[0]` goes into `open_session`; batch j reveals `seeds[j]`. All zero when k = 1.
    pub seeds: Vec<String>,
    pub calls: Vec<CallVector>,
    pub batches: Vec<BatchVector>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct CallVector {
    pub n: u32,
    pub request_hash: String,
    pub chain: String,
    pub call_id: String,
    pub ticket_message: String,
    pub ticket_signature: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct BatchVector {
    pub from: u32,
    pub to: u32,
    pub seed: String,
    /// Whether each call of the batch is proved, in order.
    pub sampled: Vec<bool>,
    pub entries: Vec<Entry>,
    pub entries_hash: String,
    pub statement: Statement,
    pub statement_message: String,
    pub statement_signature: String,
    /// `max(0, A + D − (k − 1) × F)`: the calls the vendor is paid for.
    pub paid_calls: u32,
}

/// A distinct, realistic-looking 32-byte value per call: sha256(tag ‖ n).
pub fn per_call(tag: &[u8], n: u32) -> [u8; 32] {
    let mut h = Sha256::new();
    h.update(tag);
    h.update(n.to_be_bytes());
    h.finalize().into()
}

pub fn domain() -> Domain {
    Domain::new(TESTNET_PASSPHRASE, CONTRACT_ID)
}

fn signer(seed: [u8; 32]) -> SignerVector {
    let public_key = SigningKey::from_bytes(&seed).verifying_key().to_bytes();
    SignerVector {
        seed: to_hex(&seed),
        public_key: to_hex(&public_key),
        address: keys::account_address(&public_key),
    }
}

/// `max(0, A + D − (k − 1) × F)` for a batch's entries.
pub fn paid_calls(entries: &[Entry], k: u32) -> u32 {
    let count = |r: u32| entries.iter().filter(|e| e.result == r).count() as i64;
    let paid = count(session::RESULT_ANSWERED) + count(session::RESULT_DELIVERED)
        - i64::from(k - 1) * count(session::RESULT_FAILED);
    paid.max(0) as u32
}

fn calls(session_id: &[u8; 32], count: u32) -> Vec<CallVector> {
    let ticket_key = SigningKey::from_bytes(&TICKET_KEY_SEED);
    let d = domain();
    let mut chain = *session_id;
    (1..=count)
        .map(|n| {
            let request_hash = per_call(b"request", n);
            chain = session::chain_next(&chain, &request_hash);
            CallVector {
                n,
                request_hash: to_hex(&request_hash),
                chain: to_hex(&chain),
                call_id: to_hex(&session::call_id(&CONTRACT_ID, session_id, n)),
                ticket_message: to_hex(&session::ticket_message(&d, session_id, n, &chain)),
                ticket_signature: to_hex(&session::sign_ticket(
                    &ticket_key,
                    &d,
                    session_id,
                    n,
                    &chain,
                )),
            }
        })
        .collect()
}

/// One batch over `calls[from..to]`, with `entry(n, sampled)` choosing each call's result.
fn batch(
    session_id: &[u8; 32],
    k: u32,
    seed: [u8; 32],
    calls: &[CallVector],
    from: u32,
    to: u32,
    entry: impl Fn(u32, bool) -> Entry,
) -> BatchVector {
    let verifier = SigningKey::from_bytes(&SIGNER_SEED);
    let d = domain();
    let sampled: Vec<bool> = (from + 1..=to)
        .map(|n| session::sampled(&seed, n, k))
        .collect();
    let entries: Vec<Entry> = (from + 1..=to)
        .zip(&sampled)
        .map(|(n, &s)| entry(n, s))
        .collect();
    let chain = crate::parse_hex::<32>(&calls[to as usize - 1].chain).expect("hex");
    let statement = Statement {
        session_id: *session_id,
        service_id: vectors::vector_service_id(),
        predicate_hash: PREDICATE_HASH,
        from,
        to,
        chain,
        seed,
        entries_hash: session::entries_hash(&entries),
    };
    BatchVector {
        from,
        to,
        seed: to_hex(&seed),
        sampled,
        entries_hash: to_hex(&statement.entries_hash),
        statement_message: to_hex(&session::statement_message(&d, &statement)),
        statement_signature: to_hex(&session::sign_statement(&verifier, &d, &statement)),
        paid_calls: paid_calls(&entries, k),
        entries,
        statement,
    }
}

fn proved(n: u32, delivered: bool) -> Entry {
    Entry::proved(
        delivered,
        per_call(b"presentation", n),
        per_call(b"response", n),
    )
}

/// The whole golden-vector document.
pub fn document() -> Document {
    let d = domain();

    // Every call proved: calls 1-3 in a first batch (delivered, failed, unanswered), call 4 alone.
    let plain_calls = calls(&SESSION_ID, 4);
    let zero = [0u8; 32];
    let plain = SessionVector {
        name: "every call proved (k = 1), batches of up to 8".into(),
        session_id: to_hex(&SESSION_ID),
        sample_k: 1,
        batch_size: BATCH_SIZE,
        seeds: vec![to_hex(&zero)],
        batches: vec![
            batch(&SESSION_ID, 1, zero, &plain_calls, 0, 3, |n, _| match n {
                1 => proved(n, true),
                2 => proved(n, false),
                _ => Entry::unanswered(),
            }),
            batch(&SESSION_ID, 1, zero, &plain_calls, 3, 4, |n, _| {
                proved(n, true)
            }),
        ],
        calls: plain_calls,
    };

    // One call in four proved: a full batch of 8, then a shorter last batch of 2.
    let seeds = session::seed_chain(&SEED_SECRET, 2);
    let sampled_calls = calls(&SAMPLED_SESSION_ID, 10);
    let first = batch(
        &SAMPLED_SESSION_ID,
        SAMPLE_K,
        seeds[1],
        &sampled_calls,
        0,
        BATCH_SIZE,
        |n, s| {
            let first_sampled = (1..=BATCH_SIZE)
                .find(|&m| session::sampled(&seeds[1], m, SAMPLE_K))
                .expect("a sampled call in batch 1");
            let first_unsampled = (1..=BATCH_SIZE)
                .find(|&m| !session::sampled(&seeds[1], m, SAMPLE_K))
                .expect("an unsampled call in batch 1");
            match (s, n) {
                (true, n) if n == first_sampled => proved(n, false),
                (true, n) => proved(n, true),
                (false, n) if n == first_unsampled => Entry::unanswered(),
                (false, _) => Entry::answered(),
            }
        },
    );
    let last = batch(
        &SAMPLED_SESSION_ID,
        SAMPLE_K,
        seeds[2],
        &sampled_calls,
        BATCH_SIZE,
        10,
        |n, s| {
            if s {
                proved(n, true)
            } else {
                Entry::answered()
            }
        },
    );
    let sampled = SessionVector {
        name: "one call in four proved (k = 4), batches of 8".into(),
        session_id: to_hex(&SAMPLED_SESSION_ID),
        sample_k: SAMPLE_K,
        batch_size: BATCH_SIZE,
        seeds: seeds.iter().map(|s| to_hex(s)).collect(),
        calls: sampled_calls,
        batches: vec![first, last],
    };

    Document {
        description: "Golden vectors for Fermata sessions on Stellar (docs/session-escrow.md, section 10). Generated by `cargo run -p fermata-verdict -- session-vectors`; asserted byte for byte by crates/fermata-verdict, contracts/session, packages/sdk and test-vectors/check_vectors.py. All byte strings are lower-case hex.".into(),
        ticket_tag: String::from_utf8(session::TICKET_TAG.to_vec()).expect("ASCII"),
        batch_tag: String::from_utf8(session::BATCH_TAG.to_vec()).expect("ASCII"),
        call_tag: String::from_utf8(session::CALL_TAG.to_vec()).expect("ASCII"),
        network_passphrase: TESTNET_PASSPHRASE.into(),
        network_id: to_hex(&d.network_id),
        contract: keys::contract_address(&CONTRACT_ID),
        contract_id: to_hex(&CONTRACT_ID),
        service_id: to_hex(&vectors::vector_service_id()),
        predicate_hash: to_hex(&PREDICATE_HASH),
        verifier: signer(SIGNER_SEED),
        ticket_key: signer(TICKET_KEY_SEED),
        sessions: vec![plain, sampled],
    }
}

/// The document as committed: pretty JSON with a trailing newline.
pub fn document_json() -> String {
    let mut json = serde_json::to_string_pretty(&document()).expect("serializable");
    json.push('\n');
    json
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::parse_hex;

    const COMMITTED: &str = include_str!("../../../test-vectors/session-v1.json");

    fn committed() -> Document {
        serde_json::from_str(COMMITTED).expect("test-vectors/session-v1.json parses")
    }

    /// The committed file is exactly what the generator prints.
    #[test]
    fn committed_file_is_current() {
        assert_eq!(COMMITTED, document_json());
    }

    /// Recomputes every value from the raw inputs in the file, independently of `document()`.
    #[test]
    fn committed_values_recompute() {
        let doc = committed();
        let d = Domain::new(
            &doc.network_passphrase,
            keys::contract_id(&doc.contract).unwrap(),
        );
        assert_eq!(doc.network_id, to_hex(&d.network_id));
        assert_eq!(doc.contract_id, to_hex(&d.contract_id));
        let verifier = parse_hex::<32>(&doc.verifier.public_key).unwrap();
        let ticket_key = parse_hex::<32>(&doc.ticket_key.public_key).unwrap();
        let k1 = SigningKey::from_bytes(&parse_hex::<32>(&doc.ticket_key.seed).unwrap());
        assert_eq!(k1.verifying_key().to_bytes(), ticket_key);

        for s in &doc.sessions {
            let session_id = parse_hex::<32>(&s.session_id).unwrap();
            // Tickets: the chain folds the request hashes, and each signature verifies.
            let mut chain = session_id;
            for c in &s.calls {
                chain = session::chain_next(&chain, &parse_hex::<32>(&c.request_hash).unwrap());
                assert_eq!(c.chain, to_hex(&chain));
                assert_eq!(
                    c.call_id,
                    to_hex(&session::call_id(&d.contract_id, &session_id, c.n))
                );
                let message = session::ticket_message(&d, &session_id, c.n, &chain);
                assert_eq!(c.ticket_message, to_hex(&message));
                let sig = parse_hex::<64>(&c.ticket_signature).unwrap();
                assert_eq!(
                    session::verify_ticket(&ticket_key, &d, &session_id, c.n, &chain, &sig),
                    Ok(())
                );
            }
            // Seeds: each revealed seed hashes to the one before it.
            let seeds: Vec<[u8; 32]> = s
                .seeds
                .iter()
                .map(|x| parse_hex::<32>(x).unwrap())
                .collect();
            for j in 1..seeds.len() {
                assert_eq!(<[u8; 32]>::from(Sha256::digest(seeds[j])), seeds[j - 1]);
            }
            // Batches: the sample, the entries' rules, the statement and its signature.
            let mut from = 0;
            for (j, b) in s.batches.iter().enumerate() {
                assert_eq!(b.from, from);
                let seed = parse_hex::<32>(&b.seed).unwrap();
                if s.sample_k > 1 {
                    assert_eq!(seed, seeds[j + 1]);
                }
                for (i, n) in (b.from + 1..=b.to).enumerate() {
                    let sampled = session::sampled(&seed, n, s.sample_k);
                    assert_eq!(b.sampled[i], sampled);
                    let e = &b.entries[i];
                    match e.result {
                        session::RESULT_DELIVERED | session::RESULT_FAILED => assert!(sampled),
                        session::RESULT_ANSWERED => assert!(!sampled),
                        session::RESULT_UNANSWERED => {}
                        other => panic!("result {other}"),
                    }
                }
                assert_eq!(b.entries_hash, to_hex(&session::entries_hash(&b.entries)));
                assert_eq!(b.statement.entries_hash, session::entries_hash(&b.entries));
                assert_eq!(
                    b.statement.chain,
                    parse_hex::<32>(&s.calls[b.to as usize - 1].chain).unwrap()
                );
                let message = session::statement_message(&d, &b.statement);
                assert_eq!(b.statement_message, to_hex(&message));
                let sig = parse_hex::<64>(&b.statement_signature).unwrap();
                assert_eq!(
                    session::verify_statement(&verifier, &d, &b.statement, &sig),
                    Ok(())
                );
                assert_eq!(b.paid_calls, paid_calls(&b.entries, s.sample_k));
                from = b.to;
            }
        }
        // The sampled session's first batch has every kind of entry, so the vectors cover the
        // rules: a proved failure, proved deliveries, answered and unanswered calls.
        let first = &doc.sessions[1].batches[0];
        for r in [
            session::RESULT_DELIVERED,
            session::RESULT_FAILED,
            session::RESULT_ANSWERED,
            session::RESULT_UNANSWERED,
        ] {
            assert!(first.entries.iter().any(|e| e.result == r), "result {r}");
        }
    }
}
